<script setup lang="ts">
import { computed,onMounted,ref } from 'vue';import { message } from 'ant-design-vue';import { BankOutlined, SaveOutlined, WalletOutlined } from '@ant-design/icons-vue';import UserPageLayout from '../components/UserPageLayout.vue';import { api,type ApiResponse } from '../services/api'
type Wallet={availableBalance:number;pendingBalance:number;totalPaid:number};type Bank={bankId:string;bankName:string;accountNo:string;accountName:string};type Tx={id:number;type:string;amount:number;status:string;referenceId:string|null;description:string|null;rejectReason:string|null;createdAt:string}
const wallet=ref<Wallet>({availableBalance:0,pendingBalance:0,totalPaid:0}),bank=ref<Bank>({bankId:'',bankName:'',accountNo:'',accountName:''}),history=ref<Tx[]>([]),loading=ref(true),saving=ref(false),withdrawing=ref(false),amount=ref('')
const banks=[{bankId:'970436',bankName:'Vietcombank'},{bankId:'970415',bankName:'VietinBank'},{bankId:'970418',bankName:'BIDV'},{bankId:'970405',bankName:'Agribank'},{bankId:'970422',bankName:'MB Bank'},{bankId:'970407',bankName:'Techcombank'},{bankId:'970432',bankName:'VPBank'},{bankId:'970403',bankName:'Sacombank'},{bankId:'970416',bankName:'ACB'},{bankId:'970423',bankName:'TPBank'}]
const load=async()=>{loading.value=true;try{const [w,b,h]=await Promise.all([api.get<ApiResponse<Wallet>>('/api/user/wallet'),api.get<ApiResponse<Bank|null>>('/api/user/bank-account'),api.get<ApiResponse<{transactions:Tx[]}>>('/api/user/wallet/transactions')]);if(w.data.data)wallet.value=w.data.data;if(b.data.data)bank.value=b.data.data;history.value=h.data.data?.transactions||[]}catch{message.error('Không thể tải thông tin ví.')}finally{loading.value=false}}
onMounted(load);const money=(v:number)=>new Intl.NumberFormat('vi-VN').format(Math.abs(v||0))+'đ';const chooseBank=(id:string)=>{const x=banks.find(b=>b.bankId===id);if(x)bank.value={...bank.value,...x}};const saveBank=async()=>{saving.value=true;try{const r=await api.put<ApiResponse<Bank>>('/api/user/bank-account',{bank_id:bank.value.bankId,bank_name:bank.value.bankName,account_no:bank.value.accountNo,account_name:bank.value.accountName});if(r.data.data)bank.value=r.data.data;message.success('Đã lưu tài khoản ngân hàng.')}catch(e:any){message.error(e.response?.data?.message||'Không thể lưu tài khoản.')}finally{saving.value=false}}
const amountError=computed(()=>{const v=Number(amount.value);if(!amount.value)return '';if(v<10000)return 'Số tiền rút tối thiểu là 10.000đ';if(v>wallet.value.availableBalance)return 'Số dư khả dụng không đủ';return ''});const withdraw=async()=>{if(amountError.value||!amount.value)return;withdrawing.value=true;try{await api.post('/api/user/wallet/withdraw',{amount:Number(amount.value)});message.success('Tạo yêu cầu rút tiền thành công.');amount.value='';await load()}catch(e:any){message.error(e.response?.data?.message||'Không thể rút tiền.')}finally{withdrawing.value=false}}
</script>
<template><UserPageLayout><a-spin :spinning="loading"><div class="space-y-6"><div><h1 class="text-2xl font-black text-slate-900">Ví của <span class="text-[#ee4d2d]">bạn</span></h1><p class="mt-1 text-sm text-slate-500">Quản lý số dư, tài khoản nhận tiền và lịch sử giao dịch.</p></div><div class="grid gap-4 sm:grid-cols-3"><div v-for="x in [{l:'Số dư khả dụng',v:wallet.availableBalance},{l:'Đang chờ rút',v:wallet.pendingBalance},{l:'Tổng đã rút',v:wallet.totalPaid}]" :key="x.l" class="rounded-2xl bg-white p-5 shadow-sm"><WalletOutlined class="text-xl !text-[#ee4d2d]"/><div class="mt-3 text-xs font-bold text-slate-500">{{x.l}}</div><div class="mt-1 text-2xl font-black text-slate-900">{{money(x.v)}}</div></div></div><div class="grid gap-6 lg:grid-cols-2"><a-card :bordered="false" class="!rounded-2xl"><h3 class="mb-4 flex items-center gap-2 text-sm font-black"><BankOutlined class="!text-[#ee4d2d]"/> Tài khoản ngân hàng</h3><div class="space-y-4"><div><label class="mb-1.5 block text-xs font-bold text-slate-600">Ngân hàng</label><a-select :value="bank.bankId" class="w-full" placeholder="Chọn ngân hàng" :options="banks.map(x=>({value:x.bankId,label:x.bankName}))" @change="chooseBank"/></div><div><label class="mb-1.5 block text-xs font-bold text-slate-600">Số tài khoản</label><a-input v-model:value="bank.accountNo" placeholder="Nhập số tài khoản"/></div><div><label class="mb-1.5 block text-xs font-bold text-slate-600">Tên chủ tài khoản</label><a-input v-model:value="bank.accountName" placeholder="NGUYEN VAN A" class="uppercase"/></div><a-button type="primary" block :loading="saving" class="!inline-flex !items-center !justify-center !gap-2 !border-none !bg-[#ee4d2d] hover:!bg-[#d63d1e]" @click="saveBank"><SaveOutlined/><span class="!text-white">Lưu tài khoản</span></a-button></div></a-card><a-card :bordered="false" class="!rounded-2xl"><h3 class="mb-4 text-sm font-black">Tạo yêu cầu rút tiền</h3><div class="rounded-xl bg-orange-50 p-4 text-xs text-slate-600">Tiền sẽ được chuyển tới <b>{{bank.bankName||'ngân hàng đã cấu hình'}}</b> · {{bank.accountNo||'Chưa có số tài khoản'}}</div><div class="mt-4"><label class="mb-1.5 block text-xs font-bold text-slate-600">Số tiền muốn rút</label><a-input v-model:value="amount" inputmode="numeric" placeholder="Tối thiểu 10.000đ"/><div v-if="amountError" class="mt-1 text-xs text-rose-600">{{amountError}}</div></div><a-button type="primary" block :loading="withdrawing" :disabled="!!amountError||!amount||!bank.accountNo" class="mt-4 !inline-flex !items-center !justify-center !border-none !bg-[#ee4d2d] hover:!bg-[#d63d1e]" @click="withdraw"><span class="!text-white">Yêu cầu rút tiền</span></a-button></a-card></div><a-card :bordered="false" class="!rounded-2xl" title="Lịch sử biến động ví"><div v-if="history.length" class="divide-y divide-slate-100"><div v-for="item in history" :key="item.id" class="flex items-center justify-between py-4"><div><div class="text-xs font-bold text-slate-800">{{item.description||item.referenceId||'#'+item.id}}</div><div class="mt-1 text-[10px] text-slate-400">{{new Date(item.createdAt).toLocaleString('vi-VN')}}</div></div><div class="text-right"><div class="text-sm font-black" :class="item.amount>=0?'text-emerald-600':'text-slate-800'">{{item.amount>=0?'+':'-'}}{{money(item.amount)}}</div><div class="mt-1 text-[10px] font-bold text-slate-500">{{item.status==='success'?'Thành công':item.status==='pending'?'Đang xử lý':'Đã từ chối'}}</div></div></div></div><a-empty v-else description="Chưa có giao dịch"/></a-card></div></a-spin></UserPageLayout></template>
